  v_donnaweda_id                  uuid := 'ba000001-0000-0000-0000-000000000001'::uuid;
  v_deep_decision_id                uuid := 'e03af73e-ceed-44e9-919a-02e74a1964bc'::uuid;
  v_already_complete                boolean;
begin
  -- ================================================================
  -- FRUEHER NO-OP-CHECK: ist der Zielzustand bereits vollstaendig
  -- erreicht (z. B. weil dieser Import bereits einmal erfolgreich lief)?
  -- Wenn ja: sauberer, erkannter No-op ohne jeden Write und ohne die
  -- unten folgenden strengen Vor-Import-Drift-Guards auszuloesen (deren
  -- Snapshot bewusst den ZUSTAND VOR diesem Import beschreibt und bei
  -- einem zweiten Lauf regulaer nicht mehr zutrifft).
  -- ================================================================
  select
    (select count(*) from public.repertoire_styles where status = 'active') = 322
    and not exists (
      select 1 from jsonb_to_recordset(v_band_targets_snapshot) as t(id uuid, slugs jsonb)
      where coalesce((
        select array_agg(rs.id order by ord.ordinality)
        from jsonb_array_elements_text(t.slugs) with ordinality as ord(slug, ordinality)
        join public.repertoire_styles rs on rs.slug = ord.slug
      ), '{}'::uuid[]) <> coalesce((
        select array_agg(repertoire_style_id order by sort_order)
        from public.band_repertoire_styles where band_id = t.id
      ), '{}'::uuid[])
    )
  into v_already_complete;

  if v_already_complete then
    raise notice 'ZIELSTAND BEREITS VOLLSTAENDIG ERREICHT -- kein Write noetig (erkannter No-op, z. B. weil dieser Import bereits erfolgreich lief). Katalog haelt 322 aktive Eintraege, alle 141 Zielbands entsprechen bereits exakt dem v2-Zielwert.';
    return;
  end if;

  -- ================================================================
  -- GUARD 1: genau 141 aktive Baender in Production
  -- ================================================================
  select count(*) into v_active_count from public.bands where status = 'active';
  if v_active_count <> 141 then
    raise exception 'IMPORT-GUARD FEHLGESCHLAGEN: erwartet 141 aktive Baender, tatsaechlich % -- Bandbestand hat sich seit dem Preflight veraendert', v_active_count;
  end if;

  -- ================================================================
  -- GUARD 2/3: alle 141 embedded (band_id, slug, bandname) stimmen exakt
  -- mit Production ueberein, UND keine zusaetzliche aktive Band existiert
  -- ausserhalb dieses Snapshots (Drift-Erkennung in beide Richtungen)
  -- ================================================================
  select count(*) into v_mismatch_count
  from jsonb_to_recordset(v_target_bands_snapshot) as expected(id uuid, slug text, name text)
  left join public.bands b on b.id = expected.id
  where b.id is null
     or b.slug <> expected.slug
     or b.name <> expected.name
     or b.status <> 'active';
  if v_mismatch_count <> 0 then
    raise exception 'IMPORT-GUARD FEHLGESCHLAGEN: % embedded Band-Snapshot-Zeile(n) stimmen nicht mehr mit Production ueberein (band_id/slug/name/status)', v_mismatch_count;
  end if;

  select count(*) into v_mismatch_count
  from public.bands b
  where b.status = 'active'
    and not exists (
      select 1 from jsonb_to_recordset(v_target_bands_snapshot) as expected(id uuid, slug text, name text)
      where expected.id = b.id
    );
  if v_mismatch_count <> 0 then
    raise exception 'IMPORT-GUARD FEHLGESCHLAGEN: % zusaetzliche aktive Band(s) ausserhalb des eingebetteten 141er-Snapshots gefunden -- Bandbestand ist seit dem Preflight gewachsen', v_mismatch_count;
  end if;

  -- ================================================================
  -- GUARD: die 5 ausgeschlossenen CSV-Zeilen weiterhin ohne
  -- Supabase-Datensatz; Glory Times weiterhin unveraendert als draft
  -- ================================================================
  if exists (select 1 from public.bands where name in ('Stockerholzer Buam', 'Brugger Buam', 'Björn Bussler + Band', 'Sauschwanzlbeisser', 'Soulmaid')) then
    raise exception 'IMPORT-GUARD FEHLGESCHLAGEN: mindestens eine der 5 ausgeschlossenen Bands existiert nun in public.bands -- unerwartete Drift seit dem Preflight';
  end if;

  if not exists (select 1 from public.bands where name = 'Glory Times' and status = 'draft' and is_published is false) then
    raise exception 'IMPORT-GUARD FEHLGESCHLAGEN: Glory Times entspricht nicht mehr dem erwarteten Snapshot (status=draft, is_published=false)';
  end if;

  if exists (
    select 1 from public.band_repertoire_styles brs
    join public.bands b on b.id = brs.band_id
    where b.name = 'Glory Times'
  ) then
    raise exception 'IMPORT-GUARD FEHLGESCHLAGEN: Glory Times besitzt entgegen dem Snapshot bereits repertoire_style-Zuordnungen';
  end if;

  -- ================================================================
  -- GUARD: bestehender Katalog entspricht exakt dem 3-Zeilen-Snapshot,
  -- und enthaelt insgesamt genau 3 Zeilen (kein zusaetzlicher/fehlender
  -- Eintrag seit dem Preflight)
  -- ================================================================
  select count(*) into v_mismatch_count
  from jsonb_to_recordset(v_existing_catalog_snapshot) as expected(id uuid, name text, slug text, sort_order integer)
  left join public.repertoire_styles rs on rs.id = expected.id
  where rs.id is null
     or rs.name <> expected.name
     or rs.slug <> expected.slug
     or rs.status <> 'active'
     or rs.sort_order <> expected.sort_order;
  if v_mismatch_count <> 0 then
    raise exception 'IMPORT-GUARD FEHLGESCHLAGEN: bestehender Katalog weicht vom erwarteten 3-Zeilen-Preflight-Snapshot ab (% Abweichung(en))', v_mismatch_count;
  end if;

  select count(*) into v_mismatch_count from public.repertoire_styles;
  if v_mismatch_count <> 3 then
    raise exception 'IMPORT-GUARD FEHLGESCHLAGEN: Katalog enthaelt aktuell % Zeile(n), erwartet exakt 3 vor diesem Import (unerwartete Drift seit dem Preflight)', v_mismatch_count;
  end if;

  -- ================================================================
  -- GUARD: Donnawedas bestehende 3 Zuordnungen entsprechen exakt dem
  -- Snapshot, UND keine andere Band besitzt bereits eine Zuordnung
  -- ================================================================
  select coalesce(array_agg(repertoire_style_id order by sort_order), '{}'::uuid[]) into v_current_ids
  from public.band_repertoire_styles where band_id = v_donnaweda_id;

  if v_current_ids <> (
    select array_agg((expected->>'id')::uuid order by (expected->>'sort_order')::int)
    from jsonb_array_elements(v_existing_catalog_snapshot) expected
  ) then
    raise exception 'IMPORT-GUARD FEHLGESCHLAGEN: Donnawedas bestehende repertoire_style-Zuordnungen weichen vom Preflight-Snapshot ab: %', v_current_ids::text;
  end if;

  select count(*) into v_mismatch_count
  from public.band_repertoire_styles
  where band_id <> v_donnaweda_id;
  if v_mismatch_count <> 0 then
    raise exception 'IMPORT-GUARD FEHLGESCHLAGEN: % unerwartete band_repertoire_styles-Zeile(n) bei anderen Baendern als Donnaweda gefunden -- unerwartete Drift seit dem Preflight', v_mismatch_count;
  end if;

  -- ================================================================
  -- GUARD: RPC existiert mit exakt erwarteter Signatur; benoetigte
  -- Tabellen existieren
  -- ================================================================
  if to_regprocedure('public.set_band_repertoire_styles(uuid, uuid[])') is null then
    raise exception 'IMPORT-GUARD FEHLGESCHLAGEN: RPC public.set_band_repertoire_styles(uuid, uuid[]) nicht gefunden';
  end if;

  if to_regclass('public.repertoire_styles') is null
     or to_regclass('public.band_repertoire_styles') is null
     or to_regclass('public.bands') is null then
    raise exception 'IMPORT-GUARD FEHLGESCHLAGEN: mindestens eine benoetigte Tabelle (bands/repertoire_styles/band_repertoire_styles) fehlt';
  end if;

  -- ================================================================
  -- GUARD: erwartete Anzahl fehlender Katalogeintraege (319) und
  -- Namens-/Slug-Eindeutigkeit der einzufuegenden Eintraege gegen den
  -- AKTUELLEN Katalogstand (nicht nur gegen den Preflight-Snapshot)
  -- ================================================================
  select count(*) into v_mismatch_count from jsonb_array_elements(v_catalog_inserts_snapshot);
  if v_mismatch_count <> 319 then
    raise exception 'IMPORT-GUARD FEHLGESCHLAGEN: eingebetteter Insert-Snapshot enthaelt % Eintraege, erwartet 319', v_mismatch_count;
  end if;

  select count(*) into v_mismatch_count
  from jsonb_to_recordset(v_catalog_inserts_snapshot) as ins(name text, slug text, sort_order integer)
  where exists (select 1 from public.repertoire_styles rs where rs.slug = ins.slug or rs.name = ins.name);
  if v_mismatch_count <> 0 then
    raise exception 'IMPORT-GUARD FEHLGESCHLAGEN: % geplante Insert-Zeile(n) kollidieren bereits mit vorhandenen Katalogeintraegen (Name oder Slug) -- unerwartete Drift seit dem Preflight', v_mismatch_count;
  end if;

  -- ================================================================
  -- KATALOG-INSERTS: 319 fehlende repertoire_styles anlegen
  -- ================================================================
  for v_chip_rec in
    select * from jsonb_to_recordset(v_catalog_inserts_snapshot) as t(name text, slug text, sort_order integer)
    order by sort_order
  loop
    if exists (select 1 from public.repertoire_styles where slug = v_chip_rec.slug or name = v_chip_rec.name) then
      raise exception 'IMPORT ABGEBROCHEN: geplanter Insert-Slug "%" oder Name "%" existiert bereits im Katalog (Drift waehrend des Laufs)', v_chip_rec.slug, v_chip_rec.name;
    end if;

    insert into public.repertoire_styles (name, slug, status, sort_order)
    values (v_chip_rec.name, v_chip_rec.slug, 'active', v_chip_rec.sort_order);

    v_actual_catalog_inserts := v_actual_catalog_inserts + 1;
  end loop;

  if v_actual_catalog_inserts <> 319 then
    raise exception 'IMPORT ABGEBROCHEN: % Katalog-Inserts tatsaechlich durchgefuehrt, erwartet 319', v_actual_catalog_inserts;
  end if;

  select count(*) into v_mismatch_count from public.repertoire_styles where status = 'active';
  if v_mismatch_count <> 322 then
    raise exception 'IMPORT ABGEBROCHEN: nach den Katalog-Inserts % aktive Katalogzeilen, erwartet 322', v_mismatch_count;
  end if;

  select count(distinct slug) into v_mismatch_count from public.repertoire_styles where status = 'active';
  if v_mismatch_count <> 322 then
    raise exception 'IMPORT ABGEBROCHEN: % eindeutige aktive Katalog-Slugs nach den Inserts, erwartet 322 (Slug-Kollision entstanden)', v_mismatch_count;
  end if;

  -- ================================================================
  -- BANDZUORDNUNGEN: fuer jede der 141 aktiven Zielbands den aktuellen
  -- Zustand erneut mit dem eingebetteten Zielzustand vergleichen und
  -- ausschliesslich bei tatsaechlicher Abweichung ueber die RPC setzen
  -- ================================================================
  for v_band_rec in
    select * from jsonb_to_recordset(v_band_targets_snapshot) as t(id uuid, slugs jsonb)
  loop
    select coalesce(array_agg(rs.id order by ord.ordinality), '{}'::uuid[])
      into v_target_ids
    from jsonb_array_elements_text(v_band_rec.slugs) with ordinality as ord(slug, ordinality)
    join public.repertoire_styles rs on rs.slug = ord.slug;

    if coalesce(array_length(v_target_ids, 1), 0) <> jsonb_array_length(v_band_rec.slugs) then
      raise exception 'IMPORT ABGEBROCHEN: Band % -- nicht alle Ziel-Slugs im Katalog gefunden nach den Inserts (erwartet %, gefunden %)', v_band_rec.id, jsonb_array_length(v_band_rec.slugs), coalesce(array_length(v_target_ids, 1), 0);
    end if;

    select coalesce(array_agg(repertoire_style_id order by sort_order), '{}'::uuid[]) into v_current_ids
    from public.band_repertoire_styles where band_id = v_band_rec.id;

    if v_current_ids is distinct from coalesce(v_target_ids, '{}'::uuid[]) then
      perform public.set_band_repertoire_styles(v_band_rec.id, coalesce(v_target_ids, '{}'::uuid[]));
      v_actual_rpc_calls := v_actual_rpc_calls + 1;
    end if;
  end loop;

  if v_actual_rpc_calls <> 134 then
    raise exception 'IMPORT ABGEBROCHEN: % RPC-Aufrufe tatsaechlich ausgefuehrt, erwartet 134', v_actual_rpc_calls;
  end if;

  -- ================================================================
  -- IN-TRANSACTION-ENDVERIFIKATION (vollstaendiger Zielstand)
  -- ================================================================
  select count(*) into v_mismatch_count from public.bands where status = 'active';
  if v_mismatch_count <> 141 then
    raise exception 'ENDVERIFIKATION FEHLGESCHLAGEN: % aktive Baender, erwartet 141', v_mismatch_count;
  end if;

  select count(*) into v_mismatch_count
  from public.bands b
  where b.status = 'active'
    and exists (select 1 from public.band_repertoire_styles brs where brs.band_id = b.id);
  if v_mismatch_count <> 135 then
    raise exception 'ENDVERIFIKATION FEHLGESCHLAGEN: % aktive Baender mit >=1 Zuordnung, erwartet 135', v_mismatch_count;
  end if;

  select count(*) into v_mismatch_count
  from public.bands b
  where b.status = 'active'
    and not exists (select 1 from public.band_repertoire_styles brs where brs.band_id = b.id);
  if v_mismatch_count <> 6 then
    raise exception 'ENDVERIFIKATION FEHLGESCHLAGEN: % aktive Baender ohne Zuordnung, erwartet 6', v_mismatch_count;
  end if;

  -- Jede der 141 Zielbands exakt die vorgesehenen Style-IDs in exakter
  -- Reihenfolge (erneute Iteration ueber denselben eingebetteten Snapshot)
  for v_band_rec in
    select * from jsonb_to_recordset(v_band_targets_snapshot) as t(id uuid, slugs jsonb)
  loop
    select coalesce(array_agg(rs.id order by ord.ordinality), '{}'::uuid[])
      into v_target_ids
    from jsonb_array_elements_text(v_band_rec.slugs) with ordinality as ord(slug, ordinality)
    join public.repertoire_styles rs on rs.slug = ord.slug;

    select coalesce(array_agg(repertoire_style_id order by sort_order), '{}'::uuid[]) into v_current_ids
    from public.band_repertoire_styles where band_id = v_band_rec.id;

    if v_current_ids is distinct from coalesce(v_target_ids, '{}'::uuid[]) then
      raise exception 'ENDVERIFIKATION FEHLGESCHLAGEN: Band % entspricht nach dem Import nicht exakt dem eingebetteten Zielwert (tatsaechlich %, erwartet %)', v_band_rec.id, v_current_ids::text, v_target_ids::text;
    end if;
  end loop;

  -- Deep Decision exakt "Moderne Kirchenmusik" (genau 1 Zuordnung)
  select count(*) into v_mismatch_count
  from public.band_repertoire_styles brs
  where brs.band_id = v_deep_decision_id;
  if v_mismatch_count <> 1 then
    raise exception 'ENDVERIFIKATION FEHLGESCHLAGEN: Deep Decision hat % Zuordnung(en), erwartet genau 1', v_mismatch_count;
  end if;

  select count(*) into v_mismatch_count
  from public.band_repertoire_styles brs
  join public.repertoire_styles rs on rs.id = brs.repertoire_style_id
  where brs.band_id = v_deep_decision_id and rs.name = 'Moderne Kirchenmusik';
  if v_mismatch_count <> 1 then
    raise exception 'ENDVERIFIKATION FEHLGESCHLAGEN: Deep Decision entspricht nicht exakt "Moderne Kirchenmusik"';
  end if;

  -- 322 Zielchips eindeutig aktiv im Katalog (finaler Nachweis)
  select count(*) into v_mismatch_count from public.repertoire_styles where status = 'active';
  if v_mismatch_count <> 322 then
    raise exception 'ENDVERIFIKATION FEHLGESCHLAGEN: % aktive Katalogzeilen, erwartet 322', v_mismatch_count;
  end if;

  -- Keine ausgeschlossene Band wurde durch den Import beruehrt
  if exists (select 1 from public.bands where name in ('Stockerholzer Buam', 'Brugger Buam', 'Björn Bussler + Band', 'Sauschwanzlbeisser', 'Soulmaid')) then
    raise exception 'ENDVERIFIKATION FEHLGESCHLAGEN: eine ausgeschlossene Band wurde entgegen der Vorgabe angelegt';
  end if;

  if exists (
    select 1 from public.band_repertoire_styles brs
    join public.bands b on b.id = brs.band_id
    where b.name = 'Glory Times'
  ) then
    raise exception 'ENDVERIFIKATION FEHLGESCHLAGEN: Glory Times wurde entgegen der Vorgabe veraendert';
  end if;

  raise notice 'IMPORT ERFOLGREICH: % Katalog-Inserts, % RPC-Aufruf(e). Naechster Schritt: musikalisch_verortet_verify_v2.sql ausfuehren.', v_actual_catalog_inserts, v_actual_rpc_calls;
end;
$$;
